-- Parity test for Cognos report Large_Customer_Account_Review (cluster BIL_018, 2 runs/day)
-- Generated by SemLift 1.0.0; tolerance +/-0.5% on totals
-- Measures whose numbers are expected to change (F6 aggregation correction): max_peak_demand_kw
WITH cognos AS (
    SELECT tariff.TARIFF_TYPE AS tariff_type, customer.CUSTOMER_ID AS customer_id, customer.CUSTOMER_NAME AS customer_name, customer.SERVICE_TIER AS service_tier, location.REGION AS region, SUM(meter_reading.PEAK_DEMAND_KW) AS max_peak_demand_kw
    FROM CORE.FCT_METER_READING meter_reading
    JOIN CORE.DIM_TARIFF tariff ON meter_reading.TARIFF_ID = tariff.TARIFF_ID
    JOIN CORE.DIM_METER meter ON meter_reading.METER_ID = meter.METER_ID
    JOIN CORE.DIM_CUSTOMER customer ON meter.CUSTOMER_ID = customer.CUSTOMER_ID
    JOIN CORE.DIM_LOCATION location ON meter.LOCATION_ID = location.LOCATION_ID
    GROUP BY 1, 2, 3, 4, 5
),
semantic AS (
    SELECT * FROM SEMANTIC_VIEW(
        SEM.SV_METER_CONSUMPTION
        DIMENSIONS tariff.tariff_type, customer.customer_id, customer.customer_name, customer.service_tier, location.region
        METRICS meter_reading.max_peak_demand_kw
    )
)
SELECT
    (SELECT COUNT(*) FROM cognos) AS cognos_rows,
    (SELECT COUNT(*) FROM semantic) AS semantic_rows,
    SUM(c.max_peak_demand_kw) AS cognos_max_peak_demand_kw, SUM(s.max_peak_demand_kw) AS semantic_max_peak_demand_kw,
    IFF(ABS(COALESCE(SUM(s.max_peak_demand_kw), 0) - COALESCE(SUM(c.max_peak_demand_kw), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.max_peak_demand_kw), 0)), 'PASS', 'EXPECTED_CHANGE (F6)') AS status_max_peak_demand_kw
FROM cognos c
FULL OUTER JOIN semantic s ON c.tariff_type IS NOT DISTINCT FROM s.tariff_type AND c.customer_id IS NOT DISTINCT FROM s.customer_id AND c.customer_name IS NOT DISTINCT FROM s.customer_name AND c.service_tier IS NOT DISTINCT FROM s.service_tier AND c.region IS NOT DISTINCT FROM s.region;
